(function() {
  'use strict';

  const scopeId = 'author_scope';
  const toggleBtn = document.getElementById(`${scopeId}-toggle-ref`);
  const refPanel = document.getElementById(`${scopeId}-ref-panel`);
  const canvas = document.getElementById(`${scopeId}-similarity-chart`);
  const ctx = canvas.getContext('2d');

  // 从 runtime_data 获取表格数据
  const tables = window.paperMindData?.tables || [];
  const figure12Table = tables.find(t => t.id === 'p39-figure-12');
  let chartData = { noAI: [], postAI: [] };

  if (figure12Table && figure12Table.rows) {
    figure12Table.rows.forEach(row => {
      const vals = row.values;
      if (vals['Panel'] === 'B') {
        const date = vals['Chat Date'];
        const noAiVal = vals['No AI'];
        const postAiVal = vals['Post AI'];
        if (date && noAiVal !== null && postAiVal !== null) {
          chartData.noAI.push({ date, value: parseFloat(noAiVal) });
          chartData.postAI.push({ date, value: parseFloat(postAiVal) });
        }
      }
    });
  } else {
    // 若无表格数据，使用论文明确数值作为教学示例
    chartData = {
      noAI: [
        { date: '4/1/2020', value: 0.55 },
        { date: '8/1/2020', value: 0.55 },
        { date: '12/1/2020', value: 0.55 },
        { date: '4/1/2021', value: 0.55 }
      ],
      postAI: [
        { date: '4/1/2020', value: null },
        { date: '8/1/2020', value: null },
        { date: '12/1/2020', value: 0.58 },
        { date: '4/1/2021', value: 0.61 }
      ]
    };
  }

  // 切换参照值面板
  if (toggleBtn && refPanel) {
    toggleBtn.addEventListener('click', () => {
      const isExpanded = toggleBtn.getAttribute('aria-expanded') === 'true';
      toggleBtn.setAttribute('aria-expanded', !isExpanded);
      refPanel.hidden = isExpanded;
    });
  }

  // 绘制折线图
  function drawChart() {
    if (!ctx) return;
    const width = canvas.width;
    const height = canvas.height;
    const padding = 40;
    const plotWidth = width - padding * 2;
    const plotHeight = height - padding * 2;

    ctx.clearRect(0, 0, width, height);

    // 坐标轴
    ctx.strokeStyle = '#e2e8f0';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, height - padding);
    ctx.lineTo(width - padding, height - padding);
    ctx.stroke();

    // Y 轴标签
    ctx.fillStyle = '#718096';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'right';
    ctx.fillText('0.50', padding - 5, height - padding);
    ctx.fillText('0.60', padding - 5, height - padding - plotHeight / 2);
    ctx.fillText('0.70', padding - 5, padding);

    // X 轴标签
    ctx.textAlign = 'center';
    const dates = chartData.noAI.map(d => d.date);
    const step = plotWidth / (dates.length - 1);
    dates.forEach((d, i) => {
      ctx.fillText(d, padding + i * step, height - padding + 20);
    });

    // 绘制无 AI 线（蓝色）
    ctx.strokeStyle = '#4299e1';
    ctx.lineWidth = 2;
    ctx.beginPath();
    chartData.noAI.forEach((pt, i) => {
      const x = padding + i * step;
      const y = height - padding - (pt.value - 0.5) * plotHeight * 10;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // 绘制 AI 辅助线（红色）
    ctx.strokeStyle = '#e53e3e';
    ctx.beginPath();
    chartData.postAI.forEach((pt, i) => {
      if (pt.value === null) return;
      const x = padding + i * step;
      const y = height - padding - (pt.value - 0.5) * plotHeight * 10;
      if (chartData.postAI.findIndex(p => p.value !== null) === i) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    });
    ctx.stroke();

    // 数据点
    chartData.noAI.forEach((pt, i) => {
      const x = padding + i * step;
      const y = height - padding - (pt.value - 0.5) * plotHeight * 10;
      ctx.fillStyle = '#4299e1';
      ctx.beginPath();
      ctx.arc(x, y, 4, 0, Math.PI * 2);
      ctx.fill();
    });

    chartData.postAI.forEach((pt, i) => {
      if (pt.value === null) return;
      const x = padding + i * step;
      const y = height - padding - (pt.value - 0.5) * plotHeight * 10;
      ctx.fillStyle = '#e53e3e';
      ctx.beginPath();
      ctx.moveTo(x + 4, y);
      ctx.lineTo(x - 4, y + 4);
      ctx.lineTo(x - 4, y - 4);
      ctx.fill();
    });
  }

  // 初始化绘图
  drawChart();

  // 响应式重绘
  window.addEventListener('resize', () => {
    const container = document.getElementById(`${scopeId}-chart-box`);
    if (container) {
      canvas.width = container.offsetWidth;
      canvas.height = 300;
      drawChart();
    }
  });

})();
